configFiles./etc/redis/redis.conf:
bind {{ .Settings.bind }}
port {{ .Settings.port }}
dir {{ .DataVolume.mountPath }}
protected-mode no
databases {{ .Settings.databases }}
maxclients {{ .Settings.maxclients }}
loglevel {{ .Settings.logLevel }}
appendonly {{ if .Settings.appendOnly }}yes{{ else }}no{{ end }}
appendfsync {{ .Settings.appendFsync }}
